import {renderView,section,list,form,field,textInput,textarea,button} from '../ui/view.js';import {OrganizerService} from '../services/organizer-service.js';import {el,formDataObject} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
export async function organizerView(){const [notesR,activityR]=await Promise.all([OrganizerService.notes(),OrganizerService.activity()]),notes=notesR.notes||[],activity=activityR.activity||activityR.items||[];const body=document.createDocumentFragment();body.append(section('Quick capture',[form('',[field('Title',textInput('title')),field('Note',textarea('content',{rows:5})),field('Tags',textInput('tags'))],async(fd,f)=>{const d=formDataObject(f);d.tags=String(d.tags||'').split(',').map(x=>x.trim()).filter(Boolean);await OrganizerService.saveNote(d);notify('Note saved.');organizerView();},{submitLabel:'Save note'})]));body.append(section('Project notes',[list(notes,n=>el('article',{},[el('h3',{text:n.title}),el('p',{text:n.plainText||''}),el('small',{text:(n.tags||[]).join(', ')})]),{empty:'No project notes yet.'})]));body.append(section('Recent activity',[list(activity.slice(0,50),a=>el('span',{text:`${a.action||a.type||'Activity'} ${a.createdAt||''}`}))]));renderView('Organizer',{description:'Project-specific notes, folders, tags, research, tasks, saved searches, recent activity, and archive context stay beside the creative work.',body});}
